const source = (title: string, url: string, date = checkedAt): Source => ({ title, url, checkedAt: date });
const webAction = (id: string, label: string, href: string): SetupAction => ({ id, label, kind: 'web', href, support: {} });
const downloadAction = (id: string, label: string, href: string): SetupAction => ({ id, label, kind: 'download', href, support: {} });
const localAction = (
  id: string,
  label: string,
  kind: LocalActionKind,
  command: string,
  support: LocalSupport,
  platformCommands?: Partial<Record<Platform, string>>,
  href?: string,
): SetupAction => ({ id, label, kind, command, support, ...(platformCommands ? { platformCommands } : {}), ...(href ? { href } : {}) });

type GuideDefinition = Omit<ServiceGuide, 'screenshot' | 'sources'> & { sources: Source[] };

function makeGuide(definition: GuideDefinition): ServiceGuide {
  const capture = captures.get(definition.id);
  if (!capture || !capture.screenshot || !/^https:\/\//.test(capture.sourceUrl)) {
    throw new Error(`Missing genuine public screenshot metadata for service guide: ${definition.id}`);
  }

  const screenshot: GuideScreenshot = {
    src: capture.screenshot,
    alt: capture.alt,
    caption: capture.caption,
    sourceUrl: capture.sourceUrl,
    capturedAt: capture.capturedAt,
    kind: capture.kind,
  };

  const sources = new Map<string, Source>();
  for (const item of [
    source(capture.title, capture.sourceUrl, capture.capturedAt),
    ...(capture.url && capture.url !== capture.sourceUrl ? [source(`${capture.title} (redirected page)`, capture.url, capture.capturedAt)] : []),
    ...definition.sources,
    ...definition.actions.flatMap((item) => item.href?.startsWith('https://') ? [source(item.label, item.href)] : []),
  ]) {
    sources.set(item.url, item);
  }

  return { ...definition, screenshot, sources: [...sources.values()] };
}

